export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countDistinctMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const NO_SPHINX_SCORE = 0;
const BASE_SPHINX_SCORE = 2;

const SCORE_THRESHOLDS_RICHEST_FIRST: ReadonlyArray<{
  atLeastTypes: number;
  score: number;
}> = [
  { atLeastTypes: 6, score: 5 },
  { atLeastTypes: 5, score: 3 },
];

export const scoreArmy = (army: Card[]): number => {
  if (!army.some(isSphinx)) return NO_SPHINX_SCORE;

  const typeCount = countDistinctMonsterTypes(army);
  const richestThresholdMet = SCORE_THRESHOLDS_RICHEST_FIRST.find(
    ({ atLeastTypes }) => typeCount >= atLeastTypes,
  );

  return richestThresholdMet?.score ?? BASE_SPHINX_SCORE;
};

