import { describe, it, expect } from "vitest";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const run = promisify(execFile);

const runCli = async (input: string): Promise<string> => {
  const { stdout } = await run("pnpm", ["exec", "tsx", "src/cli.ts"], {
    cwd: process.cwd(),
  });
  return stdout;
};

describe("Sphinx scoring CLI", () => {
  it("reads an army from stdin and writes the score to stdout", async () => {
    const stdout = await runCli(
      JSON.stringify({
        army: [
          { monster: "sphinx" },
          { monster: "undead-warrior", rank: 2 },
          { monster: "hydra" },
        ],
      }),
    );

    expect(JSON.parse(stdout)).toEqual({ score: 2 });
  });
});

