import { scoreArmy, type Card } from "./sphinx-score.js";

const readAll = async (stream: NodeJS.ReadStream): Promise<string> => {
  let text = "";
  for await (const chunk of stream) text += chunk;
  return text;
};

const main = async (): Promise<void> => {
  const input = await readAll(process.stdin);
  const { army } = JSON.parse(input) as { army: Card[] };
  process.stdout.write(JSON.stringify({ score: scoreArmy(army) }));
};

await main();

